(function () {
    'use strict';

    // 基于 Unlimit-Web（xcanwin/Unlimit-Web）思路修改：
    // 遍历所有元素，把 onselectstart/oncopy/onmousedown/onkeydown/oncontextmenu 等处理器
    // 覆盖为只 stopImmediatePropagation 的空操作，事件在目标元素上即被截停，
    // 页面在 document/window 上绑定的 return false / returnValue=false / preventDefault 拦截都不会触发。
    // 已移除 GM_* 依赖，适配插件 MAIN world（unsafeWindow === window）

    const $ = (Selector, el) => (el || document).querySelector(Selector);
    const $$ = (Selector, el) => (el || document).querySelectorAll(Selector);

    // 白名单：不处理这些元素（script/style/video 等），避免影响正常交互
    const allow_list = {
        element: ['script', 'style', 'video'],
        id: ['video'],
        className: ['video'],
    };

    const isIn = (el, list, type) => {
        switch (type) {
            case 'fancy': // 特殊包含：目标包含列表项
                return list.some(item => item === el || el.includes(item));
            default: // 正常包含
                return list.some(item => item === el);
        }
    };

    /* 解除单个元素上的限制 */
    const unLimit = (el = null) => {
        if (!el) return;
        if (
            isIn(el.nodeName.toLowerCase(), allow_list.element)
            || isIn(el.id ? el.id.toString().toLowerCase() : '', allow_list.id, 'fancy')
            || isIn(el.className ? el.className.toString().toLowerCase() : '', allow_list.className, 'fancy')
        ) return;

        // 1) 恢复文本选中：把 user-select 相关样式置为 unset
        [
            "user-select", "-webkit-user-select", "-moz-user-select", "-ms-user-select", "-khtml-user-select",
        ].forEach(prop => {
            const ec = el.childNodes;
            const onlyText = ec && ec.length == 1 && ec[0] && ec[0].nodeType == 3;
            const style = window.getComputedStyle(el, null)[prop];
            if (onlyText || (style && style != 'auto')) {
                el.style.setProperty(prop, "unset", "important");
            }
        });

        // 2) 覆盖选择/复制/粘贴/指针类事件处理器
        [
            "onselect", "onselectstart", "onselectionchange",
            "oncopy", "onbeforecopy",
            "onpaste", "onbeforepaste", "oncut", "onbeforecut",
            "onpointercancel", "onpointerdown", "onpointerenter", "onpointerleave", "onpointerlockchange", "onpointerlockerror", "onpointermove", "onpointerout", "onpointerover", "onpointerrawupdate", "onpointerup",
        ].forEach(evt => {
            el[evt] = e => e.stopImmediatePropagation();
        });

        // 3) 覆盖鼠标类事件处理器（仅放行 P 标签上的左键，避免干扰常规点击）
        [
            "onmouseenter", "onmousedown", "onmouseup", "onmouseout", "onmouseleave", "onmouseover",
        ].forEach(evt => {
            el[evt] = e => {
                if (["P"].indexOf(e.target.nodeName) >= 0 && e.button == 0) {
                    e.stopImmediatePropagation();
                }
            };
        });

        // 4) 覆盖键盘类事件处理器（放行 F12 与 Ctrl+C / Cmd+C）
        [
            "onkeypress", "onkeyup", "onkeydown",
        ].forEach(evt => {
            el[evt] = e => {
                const keyCode = e.keyCode || e.which || e.charCode;
                const ctrlKey = e.ctrlKey || e.metaKey;
                if ((ctrlKey && keyCode == 67) || keyCode == 123) {
                    e.stopImmediatePropagation();
                }
            };
        });

        // 5) 覆盖右键处理器（放行普通右键，跳过 SVG 中带 points 的元素）
        el.oncontextmenu = e => {
            if (e.target && e.target.points == undefined) {
                e.stopImmediatePropagation();
            }
        };
    };

    /* 枚举全部元素并解除限制 */
    const eNumUnLimit = (EL = document) => {
        if (document.documentElement) document.documentElement.classList.add('unslcl');
        $$("*", EL).forEach(unLimit);
        try {
            console.clear = () => {};
            window.debugger = () => {};
        } catch (e) {}
    };

    /* 注入文本选中样式（替代 GM_addStyle） */
    let styleInjected = false;
    const injectStyle = () => {
        if (styleInjected) return;
        const root = document.head || document.documentElement;
        if (!root) return;
        const style = document.createElement('style');
        style.textContent = "@media (prefers-color-scheme: light) { :not(foo):not(bar):not(baz):not(qux)::selection { background-color: #007BFF !important; color: white !important; } } @media (prefers-color-scheme: dark) { :not(foo):not(bar):not(baz):not(qux)::selection { background-color: #5DACDD !important; color: black !important; } }";
        root.appendChild(style);
        styleInjected = true;
    };

    // 额外保险：劫持 preventDefault，右键菜单与 F12 的 preventDefault 调用一律失效
    // （覆盖 document/window 上捕获阶段绑定的拦截）
    const nativePreventDefault = Event.prototype.preventDefault;
    Event.prototype.preventDefault = function () {
        if (this.type === 'contextmenu' || ((this.type === 'keydown' || this.type === 'keyup') && (this.keyCode === 123 || this.key === 'F12' || this.code === 'F12'))) return;
        return nativePreventDefault.apply(this, arguments);
    };

    // 动态元素监听：新增节点及其子元素立即处理
    const observer = new MutationObserver(mutations => {
        mutations.forEach(m => {
            (m.addedNodes || []).forEach(n => {
                if (n.nodeType === 1) {
                    unLimit(n);
                    if (n.querySelectorAll) n.querySelectorAll('*').forEach(unLimit);
                }
            });
        });
    });
    observer.observe(document, { subtree: true, childList: true });

    // 首次执行 + 定时兜底（页面可能反复重绑 on* 处理器）
    const run = () => {
        injectStyle();
        eNumUnLimit();
    };
    run();
    setInterval(run, 3000);
})();
